    "questionAr": "سلم منتظم وزنه $W = 20\\text{ ث.كجم}$ يستند على حائط رأسي أملس. صعد عامل وزنه $w = 55\\text{ ث.كجم}$ على السلم. احسب رد الفعل العمودي الكلي للأرض على السلم.",
