    "questionAr": "سلم منتظم طوله $L = 6\\text{ م}$ ووزنه $W = 20\\text{ ث.كجم}$ يستند على حائط رأسي أملس بزاوية ميل $\\theta = 45^\\circ$. معامل الاحتكاك السكوني مع الأرض $\\mu_s = 0.4$. صعد شخص وزنه $w = 60\\text{ ث.كجم}$ على السلم. احسب أقصى مسافة $x$ من قاعدة السلم يستطيع الشخص صعودها دون انزلاق.",
